// THE framework subpath registry — the single place a public
// `@pocketjs/framework/<subpath>` module is declared. Everything else is
// derived from this table:
//
//   - compiler import resolution (jsx-plugin.ts `packagePath`), which also
//     defines pass 1's per-framework walk set;
//   - the npm `exports` map in package.json — regenerated by
//     `bun tools/gen-exports.ts` (part of `bun run gen`) and byte-guarded by
//     tests/contract.ts, exactly the spec.rs mechanism;
//   - each execution domain's import set: the rows whose `domains` include
//     it. The UI compiler (jsx-plugin.ts packagePath), the worker bundler
//     (tools/build-worker.ts) and the type check (app-check.ts) read it.
//
// Declare a new module by adding ONE row here, then run `bun run gen`.
//
// Per-framework availability is LOAD-BEARING for byte stability: a plain
// string resolves under every framework; an object resolves only under the
// frameworks it lists, and pass 1 walks exactly what resolves — so widening
// a row changes class-string collection and therefore styles.bin bytes.
// osk/virtual-list are declared solid-only for exactly that reason: their
// npm export exists, but vue-vapor/octane builds must not silently walk (or
// resolve) their Solid-flavored implementations. gesture/kinetics keep their
// recognizer/scroller machinery in framework-neutral core modules and list a
// per-framework shim for solid and vue-vapor (octane still does not resolve
// them).

import type { PocketFramework } from "../../contracts/spec/pocket-manifest.ts";
import type { PocketDomain } from "../../contracts/spec/worker.ts";

export const POCKET_FRAMEWORKS = ["solid", "vue-vapor", "octane"] as const;

export interface SubpathDecl {
  /** Repo-relative module file. A plain string = the same file for every
   *  framework; an object = only the frameworks it lists resolve the bare
   *  form (others fall through to Bun's package.json resolution — i.e. a
   *  build error unless the row also has an npm export). */
  readonly file: string | Partial<Record<PocketFramework, string>>;
  /** npm target for the BARE export when it differs from the solid
   *  resolution (`./renderer` ships the framework-neutral shim while the
   *  compiler resolves the per-framework renderer). */
  readonly npmFile?: string;
  /** Optional generated declarations consumed by TypeScript package resolution. */
  readonly npmTypes?: string;
  /** Frameworks whose PREFIXED form (`./vue-vapor/<name>`) is also a
   *  published npm export. The bare form is always published. */
  readonly aliases?: readonly PocketFramework[];
  /** The execution domains whose bundle resolves this row; absent means the
   *  UI domain. A worker row needs one invariant file, because no UI
   *  framework resolves in that realm. */
  readonly domains?: readonly PocketDomain[];
}

/** Whether `domain`'s bundle resolves the row. */
export function resolvesIn(decl: SubpathDecl, domain: PocketDomain): boolean {
  return (decl.domains ?? ["ui"]).includes(domain);
}

const ALL = POCKET_FRAMEWORKS;
